<script lang="ts">
  import beanMascot from './assets/bean-bookkeeper.png';
  import { calcGroup, formatWeight } from '$lib/calc';
  import type { Product, RoastGroup } from '$lib/types';
  const groups: RoastGroup[] = ['House blend', 'Seasonal single origin', 'Evening decaf'].map((label,i) => ({id:String(i), label, batch_type:'standard', roast_loss_pct:15, type:'single_origin', components:[], active:true, created_at:'2026-11-21'}));
  const products: Product[] = groups.map((g,i) => ({id:String(i), group_id:g.id, name:`${g.label} · ${i===1?'1 lb':'12 oz'}`, lbs:i===1?1:.75, active:true, created_at:'2026-11-21'}));
  let quantities = $state([24,12,8]);
  let leftovers = $state([2,0,0]);
  let batch = $state(20);
  let sort = $state('type');
  let notice = $state('');
  let completed = $state(false);
  let modal = $state('');
  let dialog: HTMLDialogElement;
  const plan = $derived(groups.map((g,i) => ({...g, calc:calcGroup(g, products.map((p,j)=>({id:p.id, product_id:p.id,qty:quantities[j],production_date:'2026-11-21'})),products,leftovers[i]||0,{standard:batch||20})})));
  const sorted = $derived([...plan].sort((a,b)=>sort==='name'?a.label.localeCompare(b.label):sort==='needed'?b.calc.needed-a.calc.needed:0));
  const total = $derived(quantities.reduce((a,b)=>a+b,0));
  function open(name:string) { modal=name; dialog.showModal(); }
  function close() { dialog.close(); }
</script>
<div class="current-preview">
  <header class="account-bar"><div class="identity"><img class="bean-icon" src={beanMascot} alt="" width="54" height="60"/><span class="brand-word">BeanLedger</span><span class="tenant">Sample Roastery</span></div><div class="account">Alex <button onclick={()=>notice='Preview only. No account is signed in.'}>Log out</button></div></header>
  <main>
    <header class="planner-header"><div><h1>BeanLedger</h1><p>Coffee roaster production planner</p></div><div class="toolbar">{#each ['Pick List','Reports','Catalog','Settings','Packaging'] as action}<button onclick={()=>open(action)}>{action}</button>{/each}<button class="primary" onclick={()=>open('Finish Roast Day')}>{completed?'Completed':'Finish Roast Day'}</button><div class="date">Sat, Nov 21, 2026<span class="badge">{completed?'Completed':'Active'}</span></div></div></header>
    {#if notice}<p role="status" class="notice">{notice}</p>{/if}
    <section class="panel import"><h2>Import Orders from CSV</h2><div class="format"><label for="sample-format">Format</label><select id="sample-format"><option>Wholesale orders</option><option>Shopify export</option></select><button onclick={()=>notice='This appearance sample uses prepared orders. CSV-format editing remains in the existing app.'}>Manage formats</button></div><div class="drop-zone"><strong>Drop your CSV file here</strong><span>Prepared sample data for this visual review</span><button onclick={()=>open('Preview Import')}>Choose sample file</button></div><button class="primary wide" onclick={()=>open('Preview Import')}>Preview Import</button></section>
    <section class="panel history"><h2>Import History</h2><div class="history-row"><div><strong>wholesale-orders.csv</strong><p>Nov 21, 8:27 AM · 3 orders</p></div><button class="danger" onclick={()=>notice='Import deletion is disabled in this appearance sample.'}>Delete</button></div></section>
    <div class="sort-row"><button class="primary" onclick={()=>open('Add Manual Product')}>+ Add Manual Product</button><label><span class="sr-only">Sort roast groups</span><select bind:value={sort}><option value="type">Sort: Type</option><option value="name">Sort: Name</option><option value="needed">Sort: Amount Needed</option></select></label></div>
    <div class="groups">{#each sorted as group}{@const i=Number(group.id)}<article class="group-card"><h2>{group.label}</h2><div class="stats"><div><span>Total</span><strong>{formatWeight(group.calc.totalLbs,'lbs')}</strong></div><div><label for={'leftover-'+i}>Leftover</label><div class="leftover"><input id={'leftover-'+i} aria-label={`${group.label} leftover (lb)`} type="number" min="0" step="0.1" bind:value={leftovers[i]}/><small>lb</small></div></div><div><span>Needed</span><strong class="accent">{formatWeight(group.calc.needed,'lbs')}</strong><small>green (15% loss)</small></div></div><div class="batches"><div><span>Predicted leftover</span><strong>{formatWeight(group.calc.predictedLeftover,'lbs')}</strong></div><div><span>Batches</span><strong class="batch-number">{group.calc.batchesUp}</strong></div></div><details><summary>1 product</summary><p>{products[i].name}<b>×{quantities[i]}</b></p></details></article>{/each}</div>
    <p class="sample-note">Appearance sample · synthetic data · existing toolbar, import, history, and group-card layout</p>
  </main>
  <dialog bind:this={dialog} aria-labelledby="preview-dialog-title"><div class="dialog-header"><h2 id="preview-dialog-title">{modal}</h2><button aria-label="Close preview dialog" onclick={close}>×</button></div><div class="dialog-body">
    {#if modal==='Reports' || modal==='Pick List'}<div class="report-stats"><div><span>Total batches</span><strong>{plan.reduce((n,g)=>n+g.calc.batchesUp,0)}</strong></div><div><span>Total ordered</span><strong>{formatWeight(plan.reduce((n,g)=>n+g.calc.totalLbs,0),'lbs')}</strong></div><div><span>Total units</span><strong>{total}</strong></div></div><h3>Batches by group</h3><div class="table-wrap"><table><thead><tr><th>Group</th><th>Total</th><th>Needed</th><th>Batches</th></tr></thead><tbody>{#each plan as g}<tr><th>{g.label}</th><td>{formatWeight(g.calc.totalLbs,'lbs')}</td><td>{formatWeight(g.calc.needed,'lbs')}</td><td>{g.calc.batchesUp}</td></tr>{/each}</tbody></table></div>
    {:else if modal==='Catalog'}<div class="dialog-tabs"><strong>Products</strong><span>Roast groups</span><span>Aliases</span><span>Archived</span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Coffee weight</th><th>Packaging</th></tr></thead><tbody>{#each products as p,i}<tr><th>{p.name}</th><td>{formatWeight(p.lbs,'lbs')}</td><td>{i===1?'1 lb kraft bag':'12 oz kraft bag'}</td></tr>{/each}</tbody></table></div><p class="muted">Read-only sample of the current catalog dialog.</p>
    {:else if modal==='Packaging'}<div class="table-wrap"><table><thead><tr><th>Bag type</th><th>Starting</th><th>Filled</th><th>Remaining</th></tr></thead><tbody><tr><th>12 oz kraft bag</th><td>100</td><td>{quantities[0]+quantities[2]}</td><td>{100-quantities[0]-quantities[2]}</td></tr><tr><th>1 lb kraft bag</th><td>60</td><td>{quantities[1]}</td><td>{60-quantities[1]}</td></tr></tbody></table></div><p class="muted">Sample packaging inventory; no real stock is changed.</p>
    {:else if modal==='Settings'}<label for="sample-batch">Standard batch size (lb)</label><input id="sample-batch" type="number" min="1" max="100" bind:value={batch}/><p class="muted">Changes affect this sample only.</p>
    {:else if modal==='Finish Roast Day'}<p>Mark this sample roast day completed?</p><p class="muted">No production data is saved or inventory deducted.</p><button class="primary" onclick={()=>{completed=true;close();}}>Complete sample day</button>
    {:else}<p>{modal==='Add Manual Product'?'Adjust a sample product quantity.':'Review the prepared sample orders.'}</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Quantity</th></tr></thead><tbody>{#each products as p,i}<tr><th>{p.name}</th><td><input aria-label={`${p.name} sample quantity`} type="number" min="0" max="10000" bind:value={quantities[i]}/></td></tr>{/each}</tbody></table></div><p class="muted">Local sample only. The production import and product creation flows are unchanged.</p>{/if}
  </div><div class="dialog-footer"><button onclick={close}>Back to planner</button></div></dialog>
</div>
<style>
  .current-preview { background:var(--canvas); color:var(--ink); font-family:var(--body-font); min-height:100vh; font-size:16px; line-height:1.5; }
  .bean-icon { object-fit:contain; flex-shrink:0; }
  .account-bar { display:flex; justify-content:space-between; gap:20px; align-items:center; padding:20px 32px; border-bottom:1px solid var(--line); background:var(--surface); } .identity { display:flex; align-items:center; gap:12px; flex-wrap:wrap; } .brand-word { font-family:var(--display-font); font-size:30px; font-weight:750; letter-spacing:-.04em; } .tenant { border-left:1px solid var(--line); padding-left:16px; color:var(--muted); font-size:14px; } .account { display:flex; gap:16px; align-items:center; font-size:14px; }
  main { max-width:1300px; margin:auto; padding:36px 32px; } h1,h2,h3 { font-family:var(--heading-font); line-height:1.15; } h1 { font-size:40px; letter-spacing:-.04em; margin:0 0 8px; } h2 { font-size:23px; margin:0 0 20px; } h3 { font-size:20px; } p { margin:0 0 16px; } .planner-header { display:flex; justify-content:space-between; align-items:center; gap:24px; flex-wrap:wrap; margin-bottom:32px; } .planner-header p,.muted { color:var(--muted); } .toolbar { display:flex; gap:8px; align-items:center; flex-wrap:wrap; } .date { font-size:14px; display:flex; flex-direction:column; padding-left:8px; gap:6px; } .badge { color:var(--secondary); font-weight:700; }
  button,input,select { font:inherit; font-size:14px; color:var(--ink); background:var(--surface); border:1px solid var(--line); min-height:44px; border-radius:var(--radius); padding:10px 14px; max-width:100%; } button { cursor:pointer; font-weight:650; } button:hover { border-color:var(--ink); } button.primary { background:var(--accent); color:var(--on-accent); border-color:var(--accent); } button.danger { color:var(--accent); } select { padding-right:32px; } :focus-visible { outline:3px solid var(--secondary); outline-offset:3px; }
  .panel,.group-card { background:var(--surface); border:1px solid var(--line); border-radius:var(--radius); padding:24px; } .panel { margin-bottom:24px; } .format { display:flex; align-items:center; gap:12px; flex-wrap:wrap; margin-bottom:20px; } .format label { color:var(--muted); font-size:14px; } .drop-zone { border:1px dashed var(--line); border-radius:var(--radius); padding:26px; display:flex; flex-direction:column; gap:6px; align-items:center; margin-bottom:16px; text-align:center; } .drop-zone span { color:var(--muted); font-size:14px; } .drop-zone button { margin-top:8px; } .wide { width:100%; } .history-row { display:flex; justify-content:space-between; align-items:center; gap:16px; border:1px solid var(--line); padding:16px; border-radius:var(--radius); } .history-row p { margin:4px 0 0; font-size:14px; color:var(--muted); }
  .sort-row { display:flex; gap:12px; margin:32px 0 20px; flex-wrap:wrap; } .groups { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:20px; } .group-card h2 { font-family:var(--body-font); font-size:17px; font-weight:700; } .stats { display:grid; grid-template-columns:1fr 1fr 1fr; gap:12px; } .stats span,.stats label,.batches span { display:block; font-size:13px; color:var(--muted); } .stats strong { display:block; font-size:15px; font-variant-numeric:tabular-nums; } .stats small { font-size:12px; color:var(--muted); display:block; } .leftover { display:flex; align-items:center; gap:4px; } .leftover input { width:70px; padding:6px; } .accent { color:var(--accent); } .batches { margin-top:20px; padding-top:16px; border-top:1px solid var(--line); display:flex; justify-content:space-between; align-items:center; } .batches strong { color:var(--secondary); } .batch-number { font-size:32px; } details { margin-top:20px; font-size:14px; } summary { cursor:pointer; color:var(--muted); } details p { padding-top:12px; } details b { float:right; } .sample-note { color:var(--muted); font-size:13px; margin-top:28px; } .notice { padding:16px; border:1px solid var(--secondary); }
  dialog { background:var(--surface); color:var(--ink); border:1px solid var(--line); border-radius:var(--radius); width:min(820px,calc(100vw - 32px)); max-height:85vh; padding:0; font-family:var(--body-font); } dialog::backdrop { background:#111a22a6; } .dialog-header { display:flex; align-items:center; justify-content:space-between; padding:20px 24px; border-bottom:1px solid var(--line); } .dialog-header h2 { margin:0; } .dialog-body { padding:24px; } .dialog-footer { padding:16px 24px; border-top:1px solid var(--line); } .table-wrap { overflow:auto; } table { border-collapse:collapse; width:100%; font-size:14px; } th,td { text-align:left; padding:14px 10px; border-bottom:1px solid var(--line); } td { font-variant-numeric:tabular-nums; } td input { width:85px; } .report-stats { display:flex; gap:24px; flex-wrap:wrap; margin-bottom:32px; } .report-stats span,.report-stats strong { display:block; } .report-stats strong { font-size:28px; color:var(--secondary); } .dialog-tabs { display:flex; gap:20px; flex-wrap:wrap; margin-bottom:24px; } .sr-only { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); }
  @media(max-width:1100px) { .groups { grid-template-columns:1fr; } } @media(max-width:600px) { main { padding:24px 16px; } .account-bar { padding:16px; } .account { display:none; } .tenant { border:0; padding:0; } .panel,.group-card { padding:18px; } .brand-word { font-size:28px; } h1 { font-size:32px; } .toolbar { gap:6px; } }
</style>
